CREATE TYPE "Position" AS ENUM ('QB', 'RB', 'WR', 'TE', 'K', 'DST');
CREATE TYPE "LineupSlot" AS ENUM ('QB', 'RB', 'WR', 'TE', 'FLEX', 'SUPERFLEX', 'K', 'DST', 'BENCH');
CREATE TYPE "ScoringFormat" AS ENUM ('STANDARD', 'HALF_PPR', 'FULL_PPR', 'CUSTOM');
CREATE TYPE "RosterFormat" AS ENUM ('STANDARD', 'SUPERFLEX', 'CUSTOM');
CREATE TABLE "User" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "name" TEXT, "passwordHash" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Session" ("id" TEXT NOT NULL, "tokenHash" TEXT NOT NULL, "userId" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Team" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "userId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Team_pkey" PRIMARY KEY ("id"));
CREATE TABLE "LeagueSettings" ("id" TEXT NOT NULL, "teamId" TEXT NOT NULL, "scoringFormat" "ScoringFormat" NOT NULL DEFAULT 'HALF_PPR', "rosterFormat" "RosterFormat" NOT NULL DEFAULT 'STANDARD', "passingYardsPerPoint" DOUBLE PRECISION NOT NULL DEFAULT 25, "pointsPerPassingTd" DOUBLE PRECISION NOT NULL DEFAULT 4, "pointsPerInterception" DOUBLE PRECISION NOT NULL DEFAULT -2, "rushingYardsPerPoint" DOUBLE PRECISION NOT NULL DEFAULT 10, "pointsPerRushingTd" DOUBLE PRECISION NOT NULL DEFAULT 6, "pointsPerReception" DOUBLE PRECISION NOT NULL DEFAULT 0.5, "receivingYardsPerPoint" DOUBLE PRECISION NOT NULL DEFAULT 10, "pointsPerReceivingTd" DOUBLE PRECISION NOT NULL DEFAULT 6, "rosterSlots" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "LeagueSettings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RosterPlayer" ("id" TEXT NOT NULL, "teamId" TEXT NOT NULL, "externalId" TEXT, "name" TEXT NOT NULL, "nflTeam" TEXT NOT NULL, "position" "Position" NOT NULL, "currentSlot" "LineupSlot" NOT NULL DEFAULT 'BENCH', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "RosterPlayer_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WeeklyProjection" ("id" TEXT NOT NULL, "rosterPlayerId" TEXT NOT NULL, "season" INTEGER NOT NULL, "week" INTEGER NOT NULL, "projectedPoints" DOUBLE PRECISION NOT NULL, "floorPoints" DOUBLE PRECISION, "ceilingPoints" DOUBLE PRECISION, "consistency" DOUBLE PRECISION NOT NULL DEFAULT 0.5, "matchupRating" DOUBLE PRECISION NOT NULL DEFAULT 0, "injuryMultiplier" DOUBLE PRECISION NOT NULL DEFAULT 1, "source" TEXT NOT NULL, "sourcePayload" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "WeeklyProjection_pkey" PRIMARY KEY ("id"));
CREATE TABLE "LineupRecommendation" ("id" TEXT NOT NULL, "teamId" TEXT NOT NULL, "season" INTEGER NOT NULL, "week" INTEGER NOT NULL, "lineup" JSONB NOT NULL, "alternatives" JSONB NOT NULL, "projectedPoints" DOUBLE PRECISION NOT NULL, "confidence" DOUBLE PRECISION NOT NULL, "explanation" TEXT, "algorithmVersion" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "LineupRecommendation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WaiverRecommendation" ("id" TEXT NOT NULL, "teamId" TEXT NOT NULL, "season" INTEGER NOT NULL, "week" INTEGER NOT NULL, "addPlayer" JSONB NOT NULL, "dropPlayer" JSONB, "priorityScore" DOUBLE PRECISION NOT NULL, "shortTermValue" DOUBLE PRECISION NOT NULL, "restOfSeasonValue" DOUBLE PRECISION NOT NULL, "projectedGain" DOUBLE PRECISION NOT NULL, "explanation" TEXT, "algorithmVersion" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "WaiverRecommendation_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE UNIQUE INDEX "Session_tokenHash_key" ON "Session"("tokenHash");
CREATE INDEX "Session_userId_idx" ON "Session"("userId"); CREATE INDEX "Session_expiresAt_idx" ON "Session"("expiresAt");
CREATE INDEX "Team_userId_idx" ON "Team"("userId"); CREATE UNIQUE INDEX "LeagueSettings_teamId_key" ON "LeagueSettings"("teamId");
CREATE INDEX "RosterPlayer_teamId_position_idx" ON "RosterPlayer"("teamId", "position"); CREATE INDEX "RosterPlayer_externalId_idx" ON "RosterPlayer"("externalId");
CREATE INDEX "WeeklyProjection_season_week_idx" ON "WeeklyProjection"("season", "week"); CREATE UNIQUE INDEX "WeeklyProjection_rosterPlayerId_season_week_source_key" ON "WeeklyProjection"("rosterPlayerId", "season", "week", "source");
CREATE INDEX "LineupRecommendation_teamId_season_week_idx" ON "LineupRecommendation"("teamId", "season", "week"); CREATE INDEX "WaiverRecommendation_teamId_season_week_priorityScore_idx" ON "WaiverRecommendation"("teamId", "season", "week", "priorityScore");
ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Team" ADD CONSTRAINT "Team_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "LeagueSettings" ADD CONSTRAINT "LeagueSettings_teamId_fkey" FOREIGN KEY ("teamId") REFERENCES "Team"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "RosterPlayer" ADD CONSTRAINT "RosterPlayer_teamId_fkey" FOREIGN KEY ("teamId") REFERENCES "Team"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "WeeklyProjection" ADD CONSTRAINT "WeeklyProjection_rosterPlayerId_fkey" FOREIGN KEY ("rosterPlayerId") REFERENCES "RosterPlayer"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "LineupRecommendation" ADD CONSTRAINT "LineupRecommendation_teamId_fkey" FOREIGN KEY ("teamId") REFERENCES "Team"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "WaiverRecommendation" ADD CONSTRAINT "WaiverRecommendation_teamId_fkey" FOREIGN KEY ("teamId") REFERENCES "Team"("id") ON DELETE CASCADE ON UPDATE CASCADE;
